import {translateStatusMessage} from './statusMessages';
import {reviewedPatterns} from './i18nPatterns';
import reviewedEnglish from './i18n.en.json';
import {useEffect,useSyncExternalStore,type ReactNode} from 'react';

export type AppLanguage='es'|'en';
let activeLanguage:AppLanguage='es';
const listeners=new Set<()=>void>();
export function getLanguage(){return activeLanguage}
export function setLanguage(language:AppLanguage){if(language===activeLanguage)return;activeLanguage=language;if(typeof document!=='undefined')document.documentElement.lang=language;listeners.forEach(listener=>listener())}
export function useLanguage(){return useSyncExternalStore(callback=>{listeners.add(callback);return()=>listeners.delete(callback)},getLanguage,getLanguage)}
export function tr(spanish:string,english:string){return activeLanguage==='en'?english:spanish}
export function locale(){return activeLanguage==='en'?'en-GB':'es-ES'}

