const dictionary:Readonly<Record<string,string>>={...exact,...reviewedEnglish};
const sentencePrefixes=Object.entries(dictionary).filter(([key])=>key.length>24&&/[.!]$/.test(key)).sort(([a],[b])=>b.length-a.length);
// Translate complete clauses before applying dynamic templates. This also handles
// React text nodes split around interpolated numbers and PDF label/value rows.
export function translateText(value:string):string{
 if(activeLanguage==='es'||!value.trim())return value;
 const status=translateStatusMessage(value,translateText);if(status!==undefined)return status;
 const direct=dictionary[value.trim()];if(direct)return value.replace(value.trim(),direct);
 for(const [source,target] of sentencePrefixes){if(value.startsWith(source+' '))return target+translateText(value.slice(source.length));if(value.endsWith(' '+source))return translateText(value.slice(0,-source.length))+target}
 const separated=value.split(/(\n| · |: )/);
 const prepared=separated.map((part,index)=>index%2?part:(dictionary[part.trim()]?part.replace(part.trim(),dictionary[part.trim()]):part)).join('');
 const translated=replacements.reduce((text,[pattern,replacement])=>text.replace(pattern,replacement),prepared);
 const clauses=translated.split(/(\n| · |: )/);
 if(clauses.length>1)return clauses.map((clause,index)=>index%2?clause:translateText(clause)).join('');
 return dictionary[translated.trim()]?translated.replace(translated.trim(),dictionary[translated.trim()]):translated;
}

const originals=new WeakMap<Node,string>(),rendered=new WeakMap<Node,string>();
const attributeOriginals=new WeakMap<Element,Map<string,string>>(),attributeRendered=new WeakMap<Element,Map<string,string>>();
const translatedAttributes=['aria-label','aria-description','aria-valuetext','title','placeholder','alt','label'];
function excluded(node:Node){const element=node.nodeType===1?node as Element:node.parentElement;return Boolean(element?.closest('[translate="no"],script,style,textarea,[contenteditable="true"]'))}
function translateAttribute(element:Element,attribute:string){
 const current=element.getAttribute(attribute);if(!current)return;
 const source=attributeOriginals.get(element)??new Map<string,string>(),last=attributeRendered.get(element)??new Map<string,string>();
 if(!source.has(attribute)||current!==last.get(attribute))source.set(attribute,current);
 const next=activeLanguage==='en'?translateText(source.get(attribute)!):source.get(attribute)!;
 last.set(attribute,next);attributeOriginals.set(element,source);attributeRendered.set(element,last);
 if(current!==next)element.setAttribute(attribute,next);
}
function translateNode(node:Node){
 if(excluded(node))return;
 if(node.nodeType===3){
  const current=node.nodeValue??'';if(!current.trim())return;
  if(!originals.has(node)||current!==rendered.get(node))originals.set(node,current);
  const next=activeLanguage==='en'?translateText(originals.get(node)!):originals.get(node)!;
  rendered.set(node,next);if(current!==next)node.nodeValue=next;return;
 }
 // Node type checks work for SVG and for nodes owned by a separate window.
 if(node.nodeType!==1)return;
 for(const attribute of translatedAttributes)translateAttribute(node as Element,attribute);
 node.childNodes.forEach(translateNode);
}
export function observeLocalizedDocument(target:Document){
 const refresh=()=>{target.documentElement.lang=activeLanguage;translateNode(target.body);const title=target.querySelector('title');if(title)translateNode(title)};
 refresh();listeners.add(refresh);
 const Observer=target.defaultView?.MutationObserver??MutationObserver;
 const observer=new Observer(records=>records.forEach(record=>{
  if(record.type==='childList')record.addedNodes.forEach(translateNode);
  else if(record.type==='characterData')translateNode(record.target);
  else if(record.type==='attributes'&&record.attributeName&&!excluded(record.target))translateAttribute(record.target as Element,record.attributeName);
 }));
 observer.observe(target.body,{attributes:true,attributeFilter:translatedAttributes,characterData:true,childList:true,subtree:true});
 return()=>{listeners.delete(refresh);observer.disconnect()};
}
export function LocalizationBoundary({children}:{children:ReactNode}){
 useEffect(()=>observeLocalizedDocument(document),[]);
 return children;
}
